  expectedAnswer: string;
  options: string[];
  explanation: string;
  /**
   * Override the auto-generated example sentence. Needed for question types
   * (e.g. 用法 / 言い換え類義) where the prompt is an instruction or the
   * target phrase rather than a sentence with a blank.
   */
